import { codeBlock } from 'common-tags';
import { getLockfilePoetryVersion } from './utils.ts';

describe('modules/manager/poetry/utils', () => {
  describe('getLockfilePoetryVersion()', () => {
    it('returns the version from the lock file header', () => {
      expect(
        getLockfilePoetryVersion(
          '# This file is automatically @generated by Poetry 1.4.2 and should not be changed by hand.\n',
        ),
      ).toBe('1.4.2');
    });

    it.each`
      lockVersion | expected
      ${'1.0'}    | ${'<1.1.0'}
      ${'1.1'}    | ${'<1.3.0'}
      ${'2.0'}    | ${'>=1.3.0 <1.4.0'}
      ${'2.1'}    | ${undefined}
    `(
      'falls back to lock-version $lockVersion',
      ({ lockVersion, expected }) => {
        expect(
          getLockfilePoetryVersion(codeBlock`
            package = []

            [metadata]
            lock-version = "${lockVersion}"
          `),
        ).toBe(expected);
      },
    );

    it('returns undefined for invalid content', () => {
      expect(getLockfilePoetryVersion('not [ valid toml')).toBeUndefined();
    });
  });
});
